INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(0, 'abandon', '/əˈbændən/', 'verb', '{"zh-TW":["放棄；拋棄","遺棄"],"en":["to give up completely","to leave someone permanently"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"bandon","meaning":"control (控制)"},"logic":"離開控制，意即「放棄」。"}', 'abandon a plan/project/ship', '[{"en":"They had to abandon the project due to lack of funding.","zh-TW":"因資金不足，他們不得不放棄該計畫。"},{"en":"The crew abandoned the sinking ship.","zh-TW":"船員們棄船逃生。"}]', '{"noun":"abandonment","adjective":"abandoned"}', NULL, 3, 0, NULL),
(1, 'abandonment', '/əˈbændənmənt/', 'noun', '{"zh-TW":["放棄；廢棄"],"en":["the act of giving up ownership, a claim, or a contract"]}', NULL, 'project abandonment / abandonment of claim', '[{"en":"The insurance policy covered costs from project abandonment.","zh-TW":"保險單涵蓋了項目放棄的成本。"},{"en":"The lease provided for early abandonment without penalty after five years.","zh-TW":"租約規定五年後可以無罰款提前放棄。"}]', '{"verb":"abandon"}', NULL, 4, 1, NULL),
(2, 'abide', '/əˈbaɪd/', 'verb', '{"zh-TW":["遵守；忍受"],"en":["to accept or obey a rule or decision"]}', '{"prefix":{"text":"a-","meaning":"on (在…上)"},"root":{"text":"bide","meaning":"wait/stay (等待/停留)"},"logic":"停留在規則上，即「遵守」。"}', 'abide by rules/laws/decisions', '[{"en":"All members must abide by the association''s rules.","zh-TW":"所有會員必須遵守協會規則。"},{"en":"We expect partners to abide by the agreement.","zh-TW":"我們期望合作夥伴遵守協議。"}]', NULL, NULL, 2, 2, 628),
(3, 'ability', '/əˈbɪləti/', 'noun', '{"zh-TW":["能力；才能"],"en":["the power or skill to do something"]}', '{"root":{"text":"abil","meaning":"able (能夠)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"能夠的狀態，即「能力」。"}', 'ability to do sth', '[{"en":"She has the ability to solve complex problems.","zh-TW":"她有解決複雜問題的能力。"},{"en":"Leadership ability is essential for managers.","zh-TW":"領導能力對管理者至關重要。"}]', '{"adjective":"able","adverb":"ably"}', NULL, 3, 3, NULL),
(4, 'able', 'ˈeɪbəl', 'adjective', '{"zh-TW":["能夠；有能力","有才能的"],"en":["having the power to do something","having the skill"]}', NULL, 'able to/be able to', '[{"en":"She is able to handle multiple projects.","zh-TW":"她能夠處理多個專案。"}]', '{"noun":"ability","adverb":"ably"}', NULL, 1, 4, NULL),
(5, 'abolish', '/əˈbɒlɪʃ/', 'verb', '{"zh-TW":["廢除；廢止"],"en":["to officially end a law or system"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使離開成長，即「廢除」。"}', 'abolish a law/system/practice', '[{"en":"The government voted to abolish the outdated regulation.","zh-TW":"政府投票廢除了過時的法規。"},{"en":"Many countries have abolished the death penalty.","zh-TW":"許多國家已廢除死刑。"}]', '{"noun":"abolition"}', NULL, 3, 5, 629),
(6, 'abolition', '/ˌæbəˈlɪʃn/', 'noun', '{"zh-TW":["廢除；廢止"],"en":["the act of officially ending something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"離開成長的動作，即「廢除」。"}', 'abolition of / call for abolition', '[{"en":"The abolition of trade barriers boosted exports.","zh-TW":"廢除貿易壁壘促進了出口。"},{"en":"Some advocate for the abolition of overtime caps.","zh-TW":"有些人提倡廢除加班上限。"}]', '{"verb":"abolish"}', NULL, 3, 6, NULL),
(7, 'about', '/əˈbaʊt/', 'preposition', '{"zh-TW":["關於；大約"],"en":["concerning","approximately","concerning; approximately"]}', NULL, 'think about / about to; about + 名詞/V-ing', '[{"en":"What is this meeting about?","zh-TW":"這個會議是關於什麼的？"},{"en":"There are about 200 employees.","zh-TW":"大約有200名員工。"},{"en":"The book is about history.","zh-TW":"這本書是關於歷史的。"},{"en":"There are about 50 people here.","zh-TW":"這裡大約有50個人。"}]', '{"preposition":"about","adverb":"about"}', NULL, 2, 7, NULL),
(8, 'above', '/əˈbʌv/', 'preposition', '{"zh-TW":["在…上方；超過","在…上面；超過","在...上方；超過"],"en":["higher than","more than","in or to a higher position","at a higher level than; more than"]}', NULL, 'above all / above average; above all (最重要的是)', '[{"en":"Sales rose above expectations.","zh-TW":"銷售額超出了預期。"},{"en":"Above all, safety comes first.","zh-TW":"最重要的是，安全第一。"},{"en":"The temperature rose above 30 degrees.","zh-TW":"溫度升到了30度以上。"},{"en":"Above all, be honest.","zh-TW":"最重要的是，要誠實。"},{"en":"The plane flew above the clouds.","zh-TW":"飛機在雲層上方飛行。"},{"en":"Temperatures rose above 30 degrees.","zh-TW":"氣溫升超過30度。"}]', '{"preposition":"above","adjective":"above-mentioned"}', NULL, 2, 8, NULL),
(9, 'above-mentioned', '/əˌbʌv ˈmenʃənd/', 'adjective', '{"zh-TW":["上述的；上文所提到的"],"en":["previously mentioned in the same document"]}', NULL, 'the above-mentioned conditions / above-mentioned parties', '[{"en":"The above-mentioned requirements apply to all applicants.","zh-TW":"上述要求適用於所有申請者。"},{"en":"The above-mentioned vendors have been approved.","zh-TW":"上述供應商已獲批准。"}]', NULL, NULL, 5, 9, NULL),
(10, 'above-the-line', '/əˌbʌv ðə laɪn/', 'adjective', '{"zh-TW":["線上的；媒體廣告的"],"en":["relating to advertising that uses mass media channels to reach a wide audience"]}', NULL, 'above-the-line advertising / above-the-line promotion', '[{"en":"TV and radio are classic above-the-line advertising channels.","zh-TW":"電視和廣播是傳統的線上廣告渠道。"},{"en":"The campaign combined above-the-line and digital media.","zh-TW":"該活動結合了線上廣告和數位媒體。"}]', '{"opposite":"below-the-line"}', NULL, 5, 10, NULL),
(11, 'abrupt', '/əˈbrʌpt/', 'adjective', '{"zh-TW":["突然的；意外的"],"en":["happening suddenly or without warning"]}', NULL, 'abrupt change / abrupt departure / abrupt decision', '[{"en":"The abrupt resignation of the CEO shocked investors.","zh-TW":"執行長的突然辭職震驚了投資者。"},{"en":"An abrupt halt in production disrupted the supply chain.","zh-TW":"生產的突然停止打亂了供應鏈。"}]', '{"adverb":"abruptly","noun":"abruptness"}', NULL, 2, 11, 967),
(12, 'absence', '/ˈæbsəns/', 'noun', '{"zh-TW":["缺席；不在","缺乏"],"en":["the state of being away","the lack of something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sens","meaning":"be (存在)"},"logic":"離開存在的狀態，即「缺席」。"}', 'in the absence of / leave of absence', '[{"en":"In the absence of the manager, the assistant took charge.","zh-TW":"經理不在時，助理負責管理。"},{"en":"She took a leave of absence for personal reasons.","zh-TW":"她因私人原因請假。"}]', '{"adjective":"absent"}', NULL, 3, 12, 968),
(13, 'absenteeism', 'ˌæbsənˈtiːɪzəm', 'noun', '{"zh-TW":["缺勤；曠職","曠工"],"en":["frequent absence from work","being away without permission"]}', NULL, 'reduce absenteeism/absenteeism rate', '[{"en":"We aim to reduce absenteeism.","zh-TW":"我們致力於減少缺勤。"}]', '{"adjective":"absent"}', NULL, 4, 13, 738),
(14, 'absorb', '/əbˈzɔːrb/', 'verb', '{"zh-TW":["吸收","全神貫注"],"en":["to take in or soak up","to occupy attention fully"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sorb","meaning":"suck (吸)"},"logic":"把東西吸走，即「吸收」。"}', 'absorb information/costs; absorb information / absorb moisture', '[{"en":"The company will absorb the extra shipping costs.","zh-TW":"公司將承擔額外的運費。"},{"en":"She was completely absorbed in her research.","zh-TW":"她完全沉浸在研究中。"},{"en":"Plants absorb carbon dioxide from the air.","zh-TW":"植物從空氣中吸收二氧化碳。"},{"en":"She quickly absorbed all the new information.","zh-TW":"她很快吸收了所有新資訊。"}]', '{"noun":"absorption","adjective":"absorbing"}', NULL, 2, 14, NULL),
(15, 'abstract', '/ˈæbstrækt/', 'adjective', '{"zh-TW":["抽象的","摘要"],"en":["existing in thought but not physical","a summary of a document","existing in thought rather than having a physical existence"]}', '{"prefix":{"text":"abs-","meaning":"away (離開)"},"root":{"text":"tract","meaning":"draw (拉)"},"logic":"從具體中拉出來，即「抽象的」。"}', 'abstract concept/idea/art; abstract art / abstract concept', '[{"en":"The report includes an abstract summarizing key findings.","zh-TW":"報告包含一份摘要，概述了主要發現。"},{"en":"Abstract thinking is required for strategic planning.","zh-TW":"策略規劃需要抽象思維。"},{"en":"The painting is very abstract.","zh-TW":"這幅畫非常抽象。"},{"en":"Justice is an abstract concept.","zh-TW":"正義是一個抽象概念。"}]', '{"noun":"abstraction","adverb":"abstractly","verb":"abstract"}', NULL, 3, 15, 969),
(16, 'abundant', '/əˈbʌndənt/', 'adjective', '{"zh-TW":["豐富的；大量的"],"en":["existing in large quantities; more than enough"]}', '{"prefix":{"text":"ab-","meaning":"over (超出)"},"root":{"text":"und","meaning":"wave (波浪)"},"suffix":{"text":"-ant","meaning":"having quality (具有特質)"},"logic":"如波浪般溢出，即「豐富的」。"}', 'abundant resources/supply/evidence', '[{"en":"The region has abundant natural resources.","zh-TW":"該地區擁有豐富的自然資源。"},{"en":"There is abundant evidence to support the claim.","zh-TW":"有大量證據支持這個說法。"}]', '{"noun":"abundance","adverb":"abundantly"}', NULL, 3, 16, NULL),
(17, 'academia', '/ˌækəˈdiːmiə/', 'noun', '{"zh-TW":["學術界"],"en":["the world of universities and scholarly research"]}', NULL, 'in academia / bridge between academia and industry', '[{"en":"She spent 10 years in academia before joining the firm.","zh-TW":"她在加入公司前在學術界待了10年。"},{"en":"We bridge the gap between academia and industry.","zh-TW":"我們搭建學術界與產業界之間的橋樑。"}]', '{"noun":"academia","adjective":"academic","adverb":"academically"}', NULL, 3, 17, NULL),
(18, 'academic', '/ˌækəˈdɛmɪk/', 'adjective', '{"zh-TW":["學術的"],"en":["relating to education and studying"]}', NULL, 'academic year / academic achievement', '[{"en":"Her academic performance is excellent.","zh-TW":"她的學業成績很優秀。"},{"en":"The academic year starts in September.","zh-TW":"學年從九月開始。"}]', '{"noun":"academia","noun2":"academy"}', NULL, 3, 18, NULL),
(19, 'accelerate', '/əkˈseləreɪt/', 'verb', '{"zh-TW":["加速；促進"],"en":["to increase in speed","to cause to happen sooner"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"celer","meaning":"speed (速度)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向速度，即「加速」。"}', 'accelerate growth/development', '[{"en":"The company aims to accelerate its expansion into Asian markets.","zh-TW":"公司旨在加速擴展亞洲市場。"},{"en":"Technology has accelerated the pace of change.","zh-TW":"科技加速了變革的步伐。"}]', '{"noun":"acceleration"}', NULL, 4, 19, 632),
(20, 'accept', '/əkˈsept/', 'verb', '{"zh-TW":["接受；認可"],"en":["to agree to receive something","to believe something to be true","to agree to receive; to believe something is true"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cept","meaning":"take (拿取)"},"logic":"朝向自己拿取，即「接受」。"}', 'accept an offer/invitation; accept an offer/invitation/responsibility', '[{"en":"She accepted the job offer without hesitation.","zh-TW":"她毫不猶豫地接受了工作邀約。"},{"en":"The board accepted the proposal unanimously.","zh-TW":"董事會一致通過了該提案。"},{"en":"She accepted the job offer.","zh-TW":"她接受了這份工作。"},{"en":"He refused to accept the blame.","zh-TW":"他拒絕接受指責。"}]', '{"noun":"acceptance","adjective":"acceptable"}', NULL, 2, 20, NULL),
(21, 'acceptable', 'əkˈsɛptəbəl', 'adjective', '{"zh-TW":["可接受的；滿意的","還不錯的"],"en":["satisfactory","good enough"]}', NULL, 'acceptable quality/acceptable behavior', '[{"en":"This is an acceptable solution.","zh-TW":"這是一個可接受的解決方案。"}]', '{"noun":"acceptability","adverb":"acceptably"}', NULL, 4, 21, NULL),
(22, 'acceptance', '/ækˈsɛptəns/', 'noun', '{"zh-TW":["接受；承諾"],"en":["agreement to receive or undertake something offered"]}', NULL, 'acceptance of terms / written acceptance', '[{"en":"Please confirm your acceptance of the offer in writing.","zh-TW":"請以書面形式確認您接受此報價。"},{"en":"Acceptance of the contract terms is required before work begins.","zh-TW":"在工作開始之前需要接受合約條款。"}]', '{"verb":"accept","adjective":"accepted"}', NULL, 4, 22, NULL),
(23, 'access', '/ˈækses/', 'noun', '{"zh-TW":["進入；使用權","存取"],"en":["the opportunity to approach or enter","the right to use something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cess","meaning":"go (走)"},"logic":"走向某處，即「進入、存取」。"}', 'access to information/system', '[{"en":"Employees have access to the company database.","zh-TW":"員工可以存取公司資料庫。"},{"en":"The building provides wheelchair access.","zh-TW":"該建築提供輪椅通道。"}]', '{"adjective":"accessible","noun":"accessibility"}', NULL, 2, 23, 245),
(24, 'accident', 'ˈæksɪdənt', 'noun', '{"zh-TW":["意外；事故","偶然"],"en":["an unpleasant event that was not planned","a chance event"]}', NULL, 'car accident/work accident', '[{"en":"There was an accident on the highway.","zh-TW":"高速公路上發生了事故。"}]', '{"adjective":"accidental","adverb":"accidentally"}', NULL, 3, 24, NULL),
(25, 'accommodate', '/əˈkɒmədeɪt/', 'verb', '{"zh-TW":["容納；適應","提供住宿"],"en":["to provide lodging or room for","to adjust to fit needs"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"commod","meaning":"fit (適合)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使適合，即「容納、適應」。"}', 'accommodate guests/needs/requests', '[{"en":"The hotel can accommodate up to 500 guests.","zh-TW":"該飯店可容納最多500位客人。"},{"en":"We will try to accommodate your schedule.","zh-TW":"我們會盡量配合您的時間表。"}]', '{"noun":"accommodation"}', NULL, 4, 25, 1),
(26, 'accommodation', '/əˌkɒməˈdeɪʃən/', 'noun', '{"zh-TW":["住宿設施"],"en":["a place to stay, especially on a trip"]}', NULL, 'hotel accommodation / book accommodation', '[{"en":"The accommodation was clean and comfortable.","zh-TW":"住宿環境乾淨舒適。"},{"en":"We need to arrange accommodation for conference delegates.","zh-TW":"我們需要為與會代表安排住宿。"}]', '{"verb":"accommodate","adjective":"accommodating"}', NULL, 5, 26, NULL),
(27, 'accomplish', '/əˈkɒmplɪʃ/', 'verb', '{"zh-TW":["完成；達成"],"en":["to succeed in doing or completing something","to achieve or complete successfully"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"compli","meaning":"fill (填滿)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使填滿完成，即「完成」。"}', 'accomplish a goal/task/mission; accomplish a goal / accomplish a task', '[{"en":"She accomplished all her objectives ahead of schedule.","zh-TW":"她提前完成了所有目標。"},{"en":"What do you hope to accomplish this quarter?","zh-TW":"你希望這季度達成什麼？"},{"en":"She accomplished her goal of running a marathon.","zh-TW":"她達成了跑馬拉松的目標。"},{"en":"What do you hope to accomplish today?","zh-TW":"你今天希望完成什麼？"}]', '{"noun":"accomplishment"}', NULL, 4, 27, 634),
(28, 'accomplishment', 'əˈkɒmplɪʃmənt', 'noun', '{"zh-TW":["成就；完成","業績"],"en":["something achieved successfully","a skill or ability"]}', NULL, 'list accomplishments/key accomplishment', '[{"en":"Please list your key accomplishments.","zh-TW":"請列出您的主要成就。"}]', '{"verb":"accomplish","adjective":"accomplished"}', NULL, 5, 28, NULL),
(29, 'account', '/əˈkaʊnt/', 'noun', '{"zh-TW":["帳戶；帳目","描述；報告"],"en":["a record of money received and spent","a description of an event"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"count","meaning":"count (計算)"},"logic":"朝向計算，即「帳戶」。"}', 'bank account / on account of', '[{"en":"Please transfer the payment to our company account.","zh-TW":"請將款項匯入我們的公司帳戶。"},{"en":"She gave a detailed account of the incident.","zh-TW":"她詳細描述了該事件。"}]', '{"noun":"accountant","adjective":"accountable"}', NULL, 3, 29, 246),
(30, 'accountability', '/əˌkaʊntəˈbɪlɪti/', 'noun', '{"zh-TW":["責任；問責"],"en":["the obligation to accept responsibility for one''s actions"]}', NULL, 'corporate accountability / accountability framework', '[{"en":"Accountability is central to good corporate governance.","zh-TW":"問責制是良好公司治理的核心。"},{"en":"The CEO was held to strict accountability for the losses.","zh-TW":"首席執行官對虧損負有嚴格責任。"}]', '{"adjective":"accountable","verb":"account"}', NULL, 5, 30, 739),
(31, 'accountant', '/əˈkaʊntənt/', 'noun', '{"zh-TW":["會計師；會計人員"],"en":["a professional who maintains and audits financial records"]}', NULL, 'qualified accountant / hire an accountant / management accountant', '[{"en":"The accountant prepared the year-end financial statements.","zh-TW":"會計師準備了年末財務報表。"},{"en":"A certified accountant is required for statutory audits.","zh-TW":"法定審計需要認證會計師。"}]', '{"plural":"accountants","adjective":"accounting"}', NULL, 4, 31, NULL),
(32, 'accreditation', '/əˌkrɛdɪˈteɪʃən/', 'noun', '{"zh-TW":["認可；認證"],"en":["official recognition that a program meets established standards"]}', NULL, 'accreditation process / seek accreditation', '[{"en":"The university received accreditation from the national board.","zh-TW":"這所大學獲得了國家委員會的認可。"},{"en":"Accreditation ensures that educational programs meet quality standards.","zh-TW":"認證確保教育計劃符合品質標準。"}]', '{"verb":"accredit","adjective":"accredited"}', NULL, 5, 32, 740),
(33, 'accrual', '/əˈkruːəl/', 'noun', '{"zh-TW":["應計；累計"],"en":["an accounting method recognizing revenues and expenses when earned or incurred"]}', NULL, 'accrual accounting / accrual basis / accrual method', '[{"en":"The company reports under the accrual basis of accounting.","zh-TW":"公司採用權責發生制報告。"},{"en":"Accruals ensure expenses match the period they relate to.","zh-TW":"應計確保費用與其相關期間匹配。"}]', '{"verb":"accrue","adjective":"accrued"}', NULL, 3, 33, 741),
(34, 'accrue', '/əˈkruː/', 'verb', '{"zh-TW":["累積；應計"],"en":["to accumulate or be received as a regular gain"]}', NULL, 'accrue interest / accrue benefits / accrue overtime', '[{"en":"Interest accrues daily on the outstanding balance.","zh-TW":"利息每天在未償餘額上累積。"},{"en":"Vacation days accrue at the rate of one day per month.","zh-TW":"假期以每月一天的速度累積。"}]', '{"noun":"accrual","adjective":"accrued"}', NULL, 2, 34, 727),
(35, 'accumulate', '/əˈkjuːmjəleɪt/', 'verb', '{"zh-TW":["累積；積聚"],"en":["to gather together or acquire an increasing amount"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cumul","meaning":"heap (堆積)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使堆積起來，即「累積」。"}', 'accumulate wealth/debt/experience', '[{"en":"He accumulated considerable wealth over the years.","zh-TW":"他多年來累積了可觀的財富。"},{"en":"Dust had accumulated on the unused equipment.","zh-TW":"未使用的設備上積了灰塵。"}]', '{"noun":"accumulation"}', NULL, 4, 35, 635),
(36, 'accuracy', 'ˈækjərəsi', 'noun', '{"zh-TW":["準確性；精確度","正確性"],"en":["the quality of being correct","freedom from error"]}', NULL, 'data accuracy/improve accuracy', '[{"en":"Please check the accuracy of the figures.","zh-TW":"請核實數字的準確性。"}]', '{"adjective":"accurate","adverb":"accurately"}', NULL, 3, 36, 973),
(37, 'accurate', '/ˈækjərət/', 'adjective', '{"zh-TW":["準確的；精確的","準確的"],"en":["correct in all details; exact","correct in all details"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cur","meaning":"care (注意)"},"suffix":{"text":"-ate","meaning":"having quality (具有特質)"},"logic":"朝向注意的，即「準確的」。"}', 'accurate information/data/description; accurate information / accurate prediction', '[{"en":"Please ensure that all data entries are accurate.","zh-TW":"請確保所有資料輸入準確無誤。"},{"en":"The forecast proved to be highly accurate.","zh-TW":"該預測被證明非常準確。"},{"en":"The report contains accurate data.","zh-TW":"報告包含準確的數據。"},{"en":"Her prediction turned out to be accurate.","zh-TW":"她的預測結果證明是準確的。"}]', '{"noun":"accuracy","adverb":"accurately"}', NULL, 3, 37, 247),
(38, 'achieve', '/əˈtʃiːv/', 'verb', '{"zh-TW":["達成；實現"],"en":["to successfully reach a goal by effort"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"chieve","meaning":"come to head (完成)"},"logic":"朝向完成，即「達成」。"}', 'achieve a goal/success/results', '[{"en":"The team achieved record sales this quarter.","zh-TW":"團隊本季度達成了創紀錄的銷售額。"},{"en":"She achieved her ambition of becoming CEO.","zh-TW":"她實現了成為執行長的抱負。"}]', '{"noun":"achievement","adjective":"achievable"}', NULL, 3, 38, 248),
(39, 'achievement', '/əˈtʃiːvmənt/', 'noun', '{"zh-TW":["成就；成績"],"en":["a thing accomplished, especially by effort or skill"]}', NULL, 'academic achievement / achievement award', '[{"en":"She graduated with outstanding academic achievements.","zh-TW":"她以卓越的學業成就畢業。"},{"en":"The award recognizes the student''s remarkable achievements.","zh-TW":"該獎項表彰了學生的卓越成就。"}]', '{"verb":"achieve","adjective":"achievable"}', NULL, 4, 39, 68),
(40, 'acknowledge', '/əkˈnɒlɪdʒ/', 'verb', '{"zh-TW":["承認；確認","致謝","承認；答謝"],"en":["to accept or admit the truth of","to show that one has noticed","to accept or admit the truth of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"knowledge","meaning":"knowledge (知識)"},"logic":"朝向知道，即「承認」。"}', 'acknowledge receipt/contribution; acknowledge a mistake / acknowledge receipt', '[{"en":"The company acknowledged the error in the report.","zh-TW":"公司承認了報告中的錯誤。"},{"en":"Please acknowledge receipt of this email.","zh-TW":"請確認收到此電子郵件。"},{"en":"He acknowledged his mistake.","zh-TW":"他承認了自己的錯誤。"}]', '{"noun":"acknowledgment"}', NULL, 4, 40, 249),
(41, 'acknowledgment', '/əkˈnɒlɪdʒmənt/', 'noun', '{"zh-TW":["確認；感謝"],"en":["recognition or confirmation of receiving something"]}', NULL, 'acknowledgment of receipt / written acknowledgment', '[{"en":"Please send an acknowledgment once the package is received.","zh-TW":"收到包裹後請發送確認訊息。"},{"en":"The acknowledgment letter confirmed the application was received.","zh-TW":"確認信確認了申請書已被收到。"}]', '{"verb":"acknowledge","adjective":"acknowledged"}', NULL, 5, 41, NULL),
(42, 'acquire', '/əˈkwaɪər/', 'verb', '{"zh-TW":["獲得；取得","收購","獲得；收購"],"en":["to buy or obtain something","to learn or develop a skill","to gain possession of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quire","meaning":"seek (尋求)"},"logic":"朝向尋求，即「獲得」。"}', 'acquire skills/knowledge/company; acquire knowledge / acquire a company', '[{"en":"The firm acquired a smaller competitor last year.","zh-TW":"該公司去年收購了一家較小的競爭對手。"},{"en":"She acquired fluency in three languages.","zh-TW":"她掌握了三種語言的流利程度。"},{"en":"She acquired fluency in three languages.","zh-TW":"她習得了三種語言的流利度。"},{"en":"The company acquired a smaller competitor.","zh-TW":"公司收購了一家較小的競爭者。"}]', '{"noun":"acquisition"}', NULL, 3, 42, 2),
(43, 'acquisition', '/ˌækwɪˈzɪʃn/', 'noun', '{"zh-TW":["收購；獲得"],"en":["the purchase of one company by another","the act of obtaining something","the buying of a company","the process of gaining something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quis","meaning":"seek (尋求)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"朝向尋求的動作，即「收購」。"}', 'mergers and acquisitions / acquisition strategy; mergers and acquisitions / customer acquisition', '[{"en":"The acquisition was valued at $2 billion.","zh-TW":"此次收購估值為20億美元。"},{"en":"Customer acquisition costs have increased.","zh-TW":"客戶獲取成本增加了。"},{"en":"The acquisition was worth $2 billion.","zh-TW":"這次收購價值20億美元。"},{"en":"Customer acquisition costs are rising.","zh-TW":"客戶獲取成本正在上升。"}]', '{"verb":"acquire","noun":"acquisition"}', NULL, 4, 43, 491),
(44, 'across', '/əˈkrɒs/', 'preposition', '{"zh-TW":["橫越；在對面","穿過；橫跨","橫越；穿過；在對面"],"en":["from one side to the other","from one side to the other; on the opposite side"]}', NULL, 'come across / across from; across the street / come across; across from (在...對面)', '[{"en":"The office is across from the station.","zh-TW":"辦公室在車站對面。"},{"en":"We expanded across the region.","zh-TW":"我們擴展到整個地區。"},{"en":"She walked across the bridge.","zh-TW":"她走過了那座橋。"},{"en":"I came across an old friend.","zh-TW":"我偶然遇到了一位老朋友。"},{"en":"She walked across the street.","zh-TW":"她走過馬路。"},{"en":"The store is across from the bank.","zh-TW":"商店在銀行對面。"}]', '{"preposition":"across"}', NULL, 2, 44, NULL),
(45, 'act', 'ˈækt', 'verb', '{"zh-TW":["行動；表現","扮演"],"en":["to do something","to perform in a play"]}', NULL, 'act quickly/responsibly', '[{"en":"She acted quickly in the emergency.","zh-TW":"她在緊急情況下迅速行動。"}]', '{"noun":"action, actor","adjective":"active","adverb":"actively"}', NULL, 1, 45, NULL),
(46, 'action', 'ˈækʃən', 'noun', '{"zh-TW":["行動；措施","訴訟"],"en":["the process of doing something","a legal process"]}', NULL, 'take action/course of action', '[{"en":"We need to take immediate action.","zh-TW":"我們需要立即採取行動。"}]', '{"verb":"act","adjective":"active","adverb":"actively"}', NULL, 2, 46, NULL),
(47, 'actionable', '/ˈækʃənəbəl/', 'adjective', '{"zh-TW":["可行的；可採取行動的"],"en":["capable of being acted on; providing a basis for action"]}', NULL, 'actionable insights / actionable recommendation', '[{"en":"The report provides actionable recommendations for improvement.","zh-TW":"報告提供了可行的改進建議。"},{"en":"Good data analysis produces actionable insights for managers.","zh-TW":"良好的數據分析為管理者提供可採取行動的洞見。"}]', NULL, NULL, 4, 47, 951),
(48, 'activate', 'ˈæktɪveɪt', 'verb', '{"zh-TW":["啟動；激活","開啟"],"en":["to start something working","to put into operation"]}', NULL, 'activate an account/activate a feature', '[{"en":"Please activate your account to begin.","zh-TW":"請啟動您的帳戶以開始。"}]', '{"noun":"activation","adjective":"active","adverb":"actively"}', NULL, 3, 48, 813),
(49, 'active', 'ˈæktɪv', 'adjective', '{"zh-TW":["積極的；活躍的","主動的"],"en":["energetic and engaged","in operation"]}', NULL, 'active role/active member', '[{"en":"He plays an active role in the community.","zh-TW":"他在社區中扮演積極的角色。"}]', '{"noun":"activity","adverb":"actively"}', NULL, 2, 49, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(50, 'actual', 'ˈæktʃuəl', 'adjective', '{"zh-TW":["實際的；真正的","現實的"],"en":["existing in reality","real"]}', NULL, 'actual cost/actual results', '[{"en":"The actual cost exceeded the budget.","zh-TW":"實際成本超出了預算。"}]', '{"noun":"actuality","adverb":"actually"}', NULL, 2, 50, 814),
(51, 'acupuncture', '/ˈækjʊˌpʌŋktʃər/', 'noun', '{"zh-TW":["針灸"],"en":["a therapy involving inserting needles into the body at specific points"]}', NULL, 'receive acupuncture / acupuncture treatment', '[{"en":"She tried acupuncture to relieve chronic back pain.","zh-TW":"她嘗試針灸來緩解慢性背痛。"},{"en":"Acupuncture is widely used in traditional Chinese medicine.","zh-TW":"針灸在中醫中被廣泛使用。"}]', '{"adjective":"acupuncture"}', NULL, 4, 51, NULL),
(52, 'adapt', '/əˈdæpt/', 'verb', '{"zh-TW":["適應；改編"],"en":["to adjust to new conditions","to modify for a new purpose"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"apt","meaning":"fit (適合)"},"logic":"朝向適合，即「適應」。"}', 'adapt to changes/environment; adapt to / adapt a novel', '[{"en":"Employees must adapt to new technologies quickly.","zh-TW":"員工必須快速適應新技術。"},{"en":"The novel was adapted into a film.","zh-TW":"這部小說被改編成電影。"},{"en":"Animals must adapt to their environment.","zh-TW":"動物必須適應環境。"},{"en":"The novel was adapted into a film.","zh-TW":"這本小說被改編成電影。"}]', '{"noun":"adaptation","adjective":"adaptable"}', NULL, 2, 52, 815),
(53, 'adaptability', '/əˌdæptəˈbɪlɪti/', 'noun', '{"zh-TW":["適應能力"],"en":["the ability to adjust to new conditions or requirements quickly"]}', NULL, 'demonstrate adaptability / adaptability in the workplace / build adaptability', '[{"en":"Adaptability is increasingly valued as business environments change rapidly.","zh-TW":"隨著商業環境快速變化，適應能力日益受到重視。"},{"en":"Her adaptability made her an asset during the company restructuring.","zh-TW":"她的適應能力使她在公司重組期間成為寶貴資產。"}]', '{"adjective":"adaptable","verb":"adapt"}', NULL, 4, 53, 742),
(54, 'add', '/æd/', 'verb', '{"zh-TW":["增加；添加","增加；添加；補充說"],"en":["to put something with something else","to put something with another thing; to say something more"]}', NULL, 'add up / add to; add up (加總) / add to (增添)', '[{"en":"Add some sugar to my coffee.","zh-TW":"在我的咖啡裡加些糖。"},{"en":"The numbers don''t add up.","zh-TW":"這些數字加起來不對。"},{"en":"Please add your name to the list.","zh-TW":"請把你的名字加到名單上。"},{"en":"The rain added to our difficulties.","zh-TW":"雨水增加了我們的困難。"}]', '{"noun":"addition","adjective":"additional","adverb":"additionally"}', NULL, 1, 54, NULL),
(55, 'addendum', '/əˈdɛndəm/', 'noun', '{"zh-TW":["附錄；補充條款"],"en":["an item added to a contract or document"]}', NULL, 'add an addendum / contract addendum', '[{"en":"An addendum was attached to the agreement outlining new terms.","zh-TW":"協議附上了說明新條款的附錄。"},{"en":"Please sign the addendum to confirm the changes.","zh-TW":"請簽署附錄以確認更改。"}]', '{"plural":"addenda"}', NULL, 3, 55, NULL),
(56, 'additional', '/əˈdɪʃənl/', 'adjective', '{"zh-TW":["額外的；附加的"],"en":["extra; more than what is usual or expected"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dit","meaning":"give (給予)"},"suffix":{"text":"-ional","meaning":"relating to (有關的)"},"logic":"額外給予的，即「額外的」。"}', 'additional cost/information/support', '[{"en":"There will be an additional charge for express delivery.","zh-TW":"快遞將收取額外費用。"},{"en":"Do you need any additional information?","zh-TW":"您需要任何額外資訊嗎？"}]', '{"noun":"addition","adverb":"additionally"}', NULL, 4, 56, 816),
(57, 'address', '/əˈdres/', 'verb', '{"zh-TW":["【主要意義-名詞】地址；住址","【次要意義-動詞】處理；著手解決（問題）","【次要意義-動詞】向……發表演說；稱呼"],"en":["[primary - noun] the details of where someone lives or works","[secondary - verb] to deal with or direct attention to a problem or issue","[secondary - verb] to speak formally to a group or person"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dress","meaning":"direct (引導)"},"logic":"朝向引導，即「處理；致辭」。"}', 'address a problem / address concerns / address the audience / address the issue', '[{"en":"The new policy aims to address the growing concerns about workplace safety.","zh-TW":"新政策旨在解決對工作場所安全日益增長的擔憂。"},{"en":"The CEO addressed shareholders at the annual general meeting.","zh-TW":"執行長在年度股東大會上向股東發表演說。"},{"en":"We need to address the budget shortfall before the end of the quarter.","zh-TW":"我們需要在季度結束前解決預算短缺問題。"}]', '{"noun":"addressee","adjective":"addressable"}', '動詞 address = 「處理/解決」某問題，是 TOEIC 最高頻動詞之一，句型 address + issue/concern/problem 極為常見，考生常誤以為只有「地址」的意思。', 3, 57, 251),
(58, 'adequate', '/ˈædɪkwət/', 'adjective', '{"zh-TW":["足夠的；適當的"],"en":["sufficient for a specific need or requirement","sufficient for a specific requirement"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"equ","meaning":"equal (相等)"},"suffix":{"text":"-ate","meaning":"having quality (具有)"},"logic":"朝向相等，即「足夠的」。"}', 'adequate supply/funding/preparation; adequate supply / adequate preparation', '[{"en":"The budget is barely adequate for the project.","zh-TW":"預算勉強夠用於該專案。"},{"en":"Ensure adequate ventilation in the workspace.","zh-TW":"確保工作空間有充足的通風。"},{"en":"The hotel room was adequate for our needs.","zh-TW":"飯店房間足以滿足我們的需求。"},{"en":"Make sure you have adequate insurance.","zh-TW":"確保你有足夠的保險。"}]', '{"noun":"adequacy","adverb":"adequately"}', NULL, 3, 58, 69),
(59, 'adhere', '/ədˈhɪər/', 'verb', '{"zh-TW":["遵守；堅持","黏附"],"en":["to follow rules or guidelines closely","to stick firmly to a surface"]}', '{"prefix":{"text":"ad-","meaning":"to (朝向)"},"root":{"text":"here","meaning":"stick (黏)"},"logic":"朝向黏住，即「遵守、黏附」。"}', 'adhere to rules/policies/standards', '[{"en":"All employees must adhere to the company''s code of conduct.","zh-TW":"所有員工都必須遵守公司行為準則。"},{"en":"Please adhere to the safety guidelines at all times.","zh-TW":"請隨時遵守安全指南。"}]', '{"noun":"adherence","adjective":"adherent"}', NULL, 2, 59, 636),
(60, 'adjacent', '/əˈdʒeɪsnt/', 'adjective', '{"zh-TW":["鄰近的；毗鄰的"],"en":["next to or near something"]}', '{"prefix":{"text":"ad-","meaning":"near (靠近)"},"root":{"text":"jac","meaning":"lie (躺)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"躺在旁邊的，即「鄰近的」。"}', 'adjacent to / adjacent building/room', '[{"en":"The parking lot is adjacent to the main building.","zh-TW":"停車場緊鄰主建築。"},{"en":"We booked adjacent conference rooms for the event.","zh-TW":"我們為活動預訂了相鄰的會議室。"}]', NULL, NULL, 3, 60, 3),
(61, 'adjourn', '/əˈdʒɜːrn/', 'verb', '{"zh-TW":["休會；延期"],"en":["to suspend a meeting or session to a later time"]}', NULL, 'adjourn the meeting / adjourn until next week', '[{"en":"The chairperson adjourned the meeting after three hours.","zh-TW":"主席在三小時後宣布休會。"},{"en":"The hearing was adjourned pending new evidence.","zh-TW":"聽證會因等待新證據而被延期。"}]', '{"noun":"adjournment","adjective":"adjourned"}', NULL, 3, 61, 817),
(62, 'adjournment', '/əˈdʒɜːrnmənt/', 'noun', '{"zh-TW":["休會；延期"],"en":["the act of suspending a meeting to a later time"]}', NULL, 'motion for adjournment / meeting adjournment', '[{"en":"The adjournment allowed more time for preparation.","zh-TW":"休會提供了更多的準備時間。"},{"en":"The chairperson called for an adjournment after two hours.","zh-TW":"主席在兩小時後宣布休會。"}]', '{"verb":"adjourn"}', NULL, 4, 62, 976),
(63, 'adjust', '/əˈdʒʌst/', 'verb', '{"zh-TW":["調整；校準","調整"],"en":["to alter slightly to achieve the desired result","to alter slightly to achieve a desired result"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"just","meaning":"right (正確)"},"logic":"朝向正確，即「調整」。"}', 'adjust settings/schedule/strategy; adjust settings / adjust to', '[{"en":"We need to adjust our strategy to meet market demands.","zh-TW":"我們需要調整策略以滿足市場需求。"},{"en":"The price has been adjusted for inflation.","zh-TW":"價格已根據通膨進行調整。"},{"en":"You can adjust the temperature with this dial.","zh-TW":"你可以用這個旋鈕調整溫度。"},{"en":"It took time to adjust to the new schedule.","zh-TW":"適應新時間表需要一些時間。"}]', '{"noun":"adjustment","adjective":"adjustable"}', NULL, 2, 63, 818),
(64, 'administer', '/ədˈmɪnɪstər/', 'verb', '{"zh-TW":["管理；執行","施予"],"en":["to manage or direct","to give or apply formally","to manage or be responsible for"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"minister","meaning":"serve (服務)"},"logic":"朝向服務，即「管理」。"}', 'administer a program/test/policy; administer a program / administer medicine', '[{"en":"The HR department administers the benefits program.","zh-TW":"人力資源部門管理福利計畫。"},{"en":"The exam will be administered next Monday.","zh-TW":"考試將於下週一進行。"},{"en":"She administers the company''s finances.","zh-TW":"她管理公司的財務。"},{"en":"The nurse administered the medication.","zh-TW":"護理師給予了藥物。"}]', '{"noun":"administration","adjective":"administrative","noun2":"administrator"}', NULL, 4, 64, 638),
(65, 'administration', '/ədˌmɪnɪˈstreɪʃən/', 'noun', '{"zh-TW":["行政；管理"],"en":["the management and organization of a business or institution"]}', NULL, 'business administration / public administration / administration team', '[{"en":"The administration team handles all scheduling and correspondence.","zh-TW":"行政團隊處理所有排程和信件往來。"},{"en":"A degree in business administration is highly valued by employers.","zh-TW":"工商管理學位受到雇主的高度重視。"}]', '{"verb":"administer","adjective":"administrative","noun":"administrator"}', NULL, 5, 65, 494),
(66, 'admire', '/ədˈmaɪər/', 'verb', '{"zh-TW":["欽佩；讚賞"],"en":["to regard with respect or warm approval"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"mire","meaning":"wonder (驚嘆)"},"logic":"朝向某事物驚嘆，即「欽佩」。"}', 'admire someone for / greatly admire', '[{"en":"I admire her courage and determination.","zh-TW":"我欽佩她的勇氣和決心。"},{"en":"Everyone admires his dedication to work.","zh-TW":"每個人都讚賞他對工作的奉獻。"}]', '{"noun":"admiration","adjective":"admirable","noun2":"admirer"}', NULL, 2, 66, NULL),
(67, 'admission', '/ədˈmɪʃn/', 'noun', '{"zh-TW":["入場；入學","承認"],"en":["the process of being allowed to enter","a confession that something is true"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"miss","meaning":"send (送)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"被送入的動作，即「入場」。"}', 'admission fee/requirements/process', '[{"en":"Admission to the conference is free for members.","zh-TW":"會員可免費參加會議。"},{"en":"The admission requirements include a bachelor''s degree.","zh-TW":"入學要求包括學士學位。"}]', '{"verb":"admit"}', NULL, 3, 67, 253),
(68, 'admit', '/ədˈmɪt/', 'verb', '{"zh-TW":["承認；准許進入"],"en":["to agree something is true unwillingly","to agree that something is true; to allow to enter"]}', NULL, 'admit to / be admitted to; admit to + V-ing / be admitted to', '[{"en":"He admitted making a mistake.","zh-TW":"他承認犯了錯。"},{"en":"She was admitted to the hospital.","zh-TW":"她被送進了醫院。"},{"en":"He admitted making a mistake.","zh-TW":"他承認犯了一個錯誤。"}]', '{"noun":"admission","adjective":"admissible"}', NULL, 2, 68, NULL),
(69, 'adopt', '/əˈdɒpt/', 'verb', '{"zh-TW":["採用；採納","收養","採用；收養"],"en":["to start using a new method or idea","to legally take another''s child","to take up or start to use"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"opt","meaning":"choose (選擇)"},"logic":"朝向選擇，即「採用」。"}', 'adopt a policy/strategy/approach; adopt a policy / adopt a child', '[{"en":"The company adopted a new remote work policy.","zh-TW":"公司採用了新的遠端工作政策。"},{"en":"Several countries have adopted similar regulations.","zh-TW":"幾個國家已採用了類似法規。"},{"en":"The company adopted a new marketing strategy.","zh-TW":"公司採用了新的行銷策略。"},{"en":"They decided to adopt a child.","zh-TW":"他們決定領養一個孩子。"}]', '{"noun":"adoption","adjective":"adopted"}', NULL, 2, 69, 254),
(70, 'advance', '/ədˈvɑːns/', 'verb', '{"zh-TW":["推進；前進","預付","前進；推進"],"en":["to move forward or make progress","to pay money before it is due","to move forward","to make progress"]}', '{"prefix":{"text":"ad-","meaning":"forward (向前)"},"root":{"text":"vance","meaning":"go (走)"},"logic":"向前走，即「推進」。"}', 'advance knowledge/career/payment; advance in career / advance payment / in advance', '[{"en":"Technology continues to advance at a rapid pace.","zh-TW":"技術持續快速進步。"},{"en":"Can you advance me next month''s salary?","zh-TW":"你可以預付我下個月的薪水嗎？"},{"en":"Technology continues to advance rapidly.","zh-TW":"科技持續快速進步。"},{"en":"Please pay in advance.","zh-TW":"請預先付款。"}]', '{"noun":"advancement","adjective":"advanced"}', NULL, 3, 70, 70),
(71, 'advantage', '/ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["優勢；利益"],"en":["a condition giving a greater chance of success"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vant","meaning":"before (在前)"},"suffix":{"text":"-age","meaning":"state (狀態)"},"logic":"在前面的狀態，即「優勢」。"}', 'competitive advantage / take advantage of', '[{"en":"Our competitive advantage lies in customer service.","zh-TW":"我們的競爭優勢在於客戶服務。"},{"en":"Take advantage of the early-bird discount.","zh-TW":"把握早鳥折扣的機會。"}]', '{"adjective":"advantageous"}', NULL, 3, 71, NULL),
(72, 'adverse', '/ˈædvɜːrs/', 'adjective', '{"zh-TW":["不利的；有害的"],"en":["preventing success or development; harmful"]}', NULL, 'adverse conditions / adverse effect / adverse reaction', '[{"en":"Adverse weather conditions delayed the shipment by three days.","zh-TW":"惡劣的天氣條件使貨物延誤了三天。"},{"en":"The price increase had an adverse effect on sales volume.","zh-TW":"價格上漲對銷售量產生了不利影響。"}]', '{"adverb":"adversely","noun":"adversity"}', NULL, 3, 72, NULL),
(73, 'advertise', '/ˈædvətaɪz/', 'verb', '{"zh-TW":["做廣告；宣傳"],"en":["to describe a product in media to promote sales"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vert","meaning":"turn (轉向)"},"suffix":{"text":"-ise","meaning":"to make (使)"},"logic":"使人轉向注意，即「做廣告」。"}', 'advertise a product/position/service', '[{"en":"The company advertises heavily on social media.","zh-TW":"公司在社群媒體上大量做廣告。"},{"en":"The position was advertised in major newspapers.","zh-TW":"該職位在主要報紙上刊登廣告。"}]', '{"noun":"advertisement","noun2":"advertiser"}', NULL, 3, 73, 819),
(74, 'advertisement', '/ədˈvɜːrtɪsmənt/', 'noun', '{"zh-TW":["廣告"],"en":["a notice or announcement promoting a product or service"]}', NULL, 'run an advertisement / television advertisement', '[{"en":"The advertisement campaign reached millions of viewers.","zh-TW":"廣告活動觸達了數百萬觀眾。"},{"en":"She designed an eye-catching advertisement for the new product.","zh-TW":"她為新產品設計了引人注目的廣告。"}]', '{"verb":"advertise","noun":"advertiser","adjective":"advertised"}', NULL, 5, 74, NULL),
(75, 'advice', 'ədˈvaɪs', 'noun', '{"zh-TW":["建議；忠告","意見"],"en":["recommendation about what to do","guidance"]}', NULL, 'seek advice/give advice', '[{"en":"She sought advice from a specialist.","zh-TW":"她向專家尋求建議。"}]', '{"verb":"advise","adjective":"advisable","adverb":"advisably"}', NULL, 2, 75, NULL),
(76, 'advise', '/ədˈvaɪz/', 'verb', '{"zh-TW":["建議；勸告"],"en":["to give counsel or recommendations"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vise","meaning":"see (看)"},"logic":"朝向看清楚，即「建議」。"}', 'advise sb to do / advise against', '[{"en":"I would advise you to review the contract carefully.","zh-TW":"我建議你仔細審閱合約。"},{"en":"The consultant advised against the merger.","zh-TW":"顧問建議不要進行合併。"}]', '{"noun":"advice","noun2":"adviser","adjective":"advisable"}', NULL, 2, 76, NULL),
(77, 'advisory', '/ədˈvaɪzəri/', 'adjective', '{"zh-TW":["顧問的；諮詢的"],"en":["having the function of giving advice but not making decisions"]}', NULL, 'advisory role / advisory board / advisory committee', '[{"en":"She serves in an advisory role to the board of directors.","zh-TW":"她擔任董事會的顧問角色。"},{"en":"The advisory committee recommended reducing operational costs.","zh-TW":"諮詢委員會建議降低運營成本。"}]', '{"noun":"adviser","verb":"advise"}', NULL, 3, 77, 953),
(78, 'advocate', '/ˈædvəkeɪt/', 'verb', '{"zh-TW":["提倡；擁護"],"en":["to publicly support or recommend a cause"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"voc","meaning":"call (呼叫)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"朝向呼叫支持，即「提倡」。"}', 'advocate for change/reform/rights', '[{"en":"She advocates for better working conditions.","zh-TW":"她提倡更好的工作條件。"},{"en":"Many experts advocate a gradual approach.","zh-TW":"許多專家提倡循序漸進的方式。"}]', '{"noun":"advocacy"}', NULL, 3, 78, 640),
(79, 'affect', '/əˈfekt/', 'verb', '{"zh-TW":["【主要意義-動詞】影響；對……有影響","【次要意義-名詞（心理學）】情感；感情；情緒狀態","【次要意義-動詞（正式）】假裝；裝出（某種態度）"],"en":["[primary - verb] to have an effect or influence on something","[secondary - noun (psychology)] an emotion or feeling as a component of behavior","[secondary - verb] to pretend or assume something falsely"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"logic":"朝向作用，即「影響」。"}', 'affect the outcome / affect sales / flat affect / affected speech', '[{"en":"The sudden change in policy will affect all existing contract holders.","zh-TW":"政策的突然改變將影響所有現有合約持有人。"},{"en":"The patient showed signs of flat affect following the treatment.","zh-TW":"患者在治療後表現出情感平淡的跡象。"},{"en":"His affected manner of speaking annoyed some of his colleagues.","zh-TW":"他做作的說話方式令一些同事感到惱火。"}]', '{"noun":"effect (different word!)","adjective":"affected, affective"}', 'affect（動詞）= 「影響」，與 effect（名詞/動詞）區別是 TOEIC 必考文法點；名詞 affect（心理學術語 = 情感）較少見但出現在醫療文章中，affected（adj.）= 「裝出來的/做作的」。', 2, 79, 255),
(80, 'affection', '/əˈfekʃn/', 'noun', '{"zh-TW":["情感；喜愛"],"en":["a gentle feeling of fondness or love"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"對某人產生感情的狀態。"}', 'show affection / deep affection', '[{"en":"She showed great affection for her grandchildren.","zh-TW":"她對孫子們表現出極大的喜愛。"},{"en":"He has a deep affection for his hometown.","zh-TW":"他對故鄉有深厚的感情。"}]', '{"adjective":"affectionate"}', NULL, 3, 80, NULL),
(81, 'affidavit', '/ˌæfɪˈdeɪvɪt/', 'noun', '{"zh-TW":["宣誓書；書面陳述"],"en":["a written statement confirmed by oath"]}', NULL, 'sign an affidavit / sworn affidavit', '[{"en":"The witness signed an affidavit confirming the events.","zh-TW":"證人簽署了確認事件的宣誓書。"},{"en":"Submit an affidavit along with your application.","zh-TW":"請隨申請書一併提交宣誓書。"}]', NULL, NULL, 3, 81, NULL),
(82, 'affiliate', '/əˈfɪlieɪt/', 'verb', '{"zh-TW":["使隸屬；使加入","附屬機構"],"en":["to officially attach or connect to an organization"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fili","meaning":"son (子)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為兒子般的關係，即「隸屬」。"}', 'affiliate with / affiliated company', '[{"en":"The institute is affiliated with a major university.","zh-TW":"該研究所隸屬於一所主要大學。"},{"en":"Our affiliate offices handle regional operations.","zh-TW":"我們的附屬辦公室處理區域業務。"}]', '{"noun":"affiliation"}', NULL, 3, 82, 978),
(83, 'affiliation', '/əˌfɪliˈeɪʃən/', 'noun', '{"zh-TW":["聯繫；附屬關係"],"en":["the state of being affiliated with or connected to an organization"]}', NULL, 'professional affiliation / affiliation agreement', '[{"en":"She listed all her professional affiliations on the form.","zh-TW":"她在表格上列出了所有專業聯繫。"},{"en":"The two companies formalized their affiliation agreement.","zh-TW":"兩家公司正式簽署了附屬關係協議。"}]', '{"verb":"affiliate","adjective":"affiliated"}', NULL, 4, 83, 497),
(84, 'afford', '/əˈfɔːrd/', 'verb', '{"zh-TW":["負擔得起","提供"],"en":["to have enough money to pay for","to provide or supply"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"ford","meaning":"further (推進)"},"logic":"朝向推進足夠的，即「負擔得起」。"}', 'afford to buy/pay / can''t afford', '[{"en":"The company cannot afford to lose any more clients.","zh-TW":"公司承受不起再失去任何客戶。"},{"en":"The new location affords a beautiful view.","zh-TW":"新地點提供了美麗的景觀。"}]', '{"adjective":"affordable"}', NULL, 2, 84, 256),
(85, 'affordable', '/əˈfɔːrdəbl/', 'adjective', '{"zh-TW":["負擔得起的"],"en":["inexpensive enough for most people"]}', '{"root":{"text":"afford","meaning":"provide (提供)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠負擔的。"}', 'affordable housing / affordable price', '[{"en":"We need more affordable housing in the city.","zh-TW":"我們城市需要更多平價住宅。"},{"en":"The restaurant offers good food at affordable prices.","zh-TW":"這家餐廳以實惠的價格提供美食。"}]', '{"verb":"afford"}', NULL, 4, 85, 820),
(86, 'afraid', '/əˈfreɪd/', 'adjective', '{"zh-TW":["害怕的；恐怕","害怕的；擔心的"],"en":["feeling fear or anxiety","feeling fear; worried about something"]}', NULL, 'afraid of / I''m afraid; be afraid of / I''m afraid (that)...', '[{"en":"She is afraid of spiders.","zh-TW":"她怕蜘蛛。"},{"en":"I''m afraid I can''t help.","zh-TW":"恐怕我幫不了你。"},{"en":"I''m afraid we''re sold out.","zh-TW":"恐怕我們賣完了。"}]', NULL, NULL, 2, 86, NULL),
(87, 'afternoon', '/ˌɑːftəˈnuːn/', 'noun', '{"zh-TW":["下午"],"en":["the period between midday and evening"]}', NULL, 'in the afternoon / this afternoon', '[{"en":"The meeting is scheduled for this afternoon.","zh-TW":"會議安排在今天下午。"},{"en":"She usually takes a nap in the afternoon.","zh-TW":"她通常在下午小睡。"}]', NULL, NULL, 3, 87, NULL),
(88, 'again', '/əˈɡɛn/', 'adverb', '{"zh-TW":["再一次；又"],"en":["one more time"]}', NULL, 'once again / again and again', '[{"en":"Please try again later.","zh-TW":"請稍後再試。"},{"en":"Once again, thank you all.","zh-TW":"再次感謝大家。"}]', '{"adverb":"again"}', NULL, 2, 88, NULL),
(89, 'against', '/əˈɡɛnst/', 'preposition', '{"zh-TW":["反對；靠著"],"en":["in opposition to","leaning on"]}', NULL, 'against the rules / go against', '[{"en":"This is against company policy.","zh-TW":"這違反公司政策。"},{"en":"He leaned against the desk.","zh-TW":"他靠在書桌上。"}]', '{"preposition":"against"}', NULL, 3, 89, NULL),
(90, 'age', '/eɪdʒ/', 'noun', '{"zh-TW":["年齡；時代"],"en":["the number of years someone has lived"]}', NULL, 'at the age of / old age', '[{"en":"She started working at the age of 18.","zh-TW":"她18歲開始工作。"},{"en":"We live in the digital age.","zh-TW":"我們生活在數位時代。"}]', '{"verb":"age","adjective":"aged"}', NULL, 1, 90, NULL),
(91, 'agenda', '/əˈdʒendə/', 'noun', '{"zh-TW":["議程；待辦事項"],"en":["a list of items to be discussed at a meeting"]}', '{"root":{"text":"ag","meaning":"do (做)"},"suffix":{"text":"-enda","meaning":"things to be done (待做的事)"},"logic":"待做的事，即「議程」。"}', 'meeting agenda / on the agenda', '[{"en":"The first item on the agenda is the budget review.","zh-TW":"議程上的第一項是預算審查。"},{"en":"Please distribute the agenda before the meeting.","zh-TW":"請在會議前分發議程。"}]', NULL, NULL, 2, 91, 71),
(92, 'agenda-setting', '/əˈdʒendə ˈsetɪŋ/', 'noun', '{"zh-TW":["議程設定"],"en":["the ability to determine the topics and priorities of discussion"]}', NULL, 'agenda-setting power / agenda-setting role', '[{"en":"The chairperson has agenda-setting authority in the meeting.","zh-TW":"主席在會議中擁有議程設定權力。"},{"en":"Effective agenda-setting ensures productive meetings.","zh-TW":"有效的議程設定確保高效的會議。"}]', NULL, NULL, 5, 92, NULL),
(93, 'aggregate', '/ˈæɡrɪɡɪt/', 'adjective', '{"zh-TW":["總計的；總體的"],"en":["formed by the combination of many items"]}', NULL, 'aggregate demand / aggregate data', '[{"en":"Aggregate sales data showed a 15% increase over last year.","zh-TW":"總計銷售數據顯示比去年增長了15%。"},{"en":"The aggregate cost of the project exceeded five million dollars.","zh-TW":"項目的總成本超過了五百萬元。"}]', '{"verb":"aggregate","noun":"aggregate"}', NULL, 3, 93, 498),
(94, 'aggressive', '/əˈɡresɪv/', 'adjective', '{"zh-TW":["積極進取的","侵略的","侵略性的；積極進取的"],"en":["pursuing goals forcefully","hostile or violent"]}', '{"prefix":{"text":"ag-","meaning":"toward (朝向)"},"root":{"text":"gress","meaning":"step (踏步)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"朝向踏步的，即「積極進取的」。"}', 'aggressive strategy/marketing/growth; aggressive behavior / aggressive marketing', '[{"en":"The firm adopted an aggressive expansion strategy.","zh-TW":"該公司採用了積極的擴張策略。"},{"en":"Aggressive marketing helped boost brand awareness.","zh-TW":"積極的行銷幫助提升了品牌知名度。"},{"en":"The dog became aggressive toward strangers.","zh-TW":"這隻狗對陌生人變得有攻擊性。"},{"en":"The company adopted an aggressive marketing strategy.","zh-TW":"公司採取了積極的行銷策略。"}]', '{"noun":"aggression","adverb":"aggressively"}', NULL, 4, 94, 821),
(95, 'agile', '/ˈædʒaɪl/', 'adjective', '{"zh-TW":["敏捷的；靈活的"],"en":["able to move quickly and easily; using agile development methods"]}', NULL, 'agile team / agile approach / agile development / agile mindset', '[{"en":"The agile team delivered new features every two weeks.","zh-TW":"敏捷團隊每兩週交付新功能。"},{"en":"Staying agile allows the company to respond quickly to market changes.","zh-TW":"保持敏捷使公司能夠快速響應市場變化。"}]', '{"noun":"agility","adverb":"agilely"}', NULL, 2, 95, 822),
(96, 'agree', '/əˈɡriː/', 'verb', '{"zh-TW":["同意；贊成","同意；一致"],"en":["to have the same opinion; to consent","to have the same opinion","to have the same opinion; to say yes"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"gree","meaning":"pleasing (令人滿意)"},"logic":"朝向令人滿意，即「同意」。"}', 'agree on/to/with / agree to terms; agree with / agree on; agree with sb / agree to do sth / agree on sth', '[{"en":"Both parties agreed to the terms of the contract.","zh-TW":"雙方同意了合約條款。"},{"en":"I agree with your assessment of the situation.","zh-TW":"我同意你對情況的評估。"},{"en":"I agree with your suggestion.","zh-TW":"我同意你的建議。"},{"en":"They agreed on a price.","zh-TW":"他們就價格達成了一致。"},{"en":"They agreed to postpone the meeting.","zh-TW":"他們同意延後會議。"}]', '{"noun":"agreement","adjective":"agreeable"}', NULL, 2, 96, NULL),
(97, 'agreement', '/əˈɡriːmənt/', 'noun', '{"zh-TW":["協議；合約"],"en":["a formal arrangement between parties"]}', NULL, 'sign an agreement / reach an agreement', '[{"en":"Both parties signed the agreement last Monday.","zh-TW":"雙方上週一簽署了協議。"},{"en":"The terms of the agreement must be met by both sides.","zh-TW":"協議條款必須由雙方遵守。"}]', '{"verb":"agree","adjective":"agreed"}', NULL, 3, 97, 72),
(98, 'agriculture', '/ˈæɡrɪkʌltʃər/', 'noun', '{"zh-TW":["農業"],"en":["the science or practice of farming"]}', '{"root":{"text":"agri","meaning":"field (田地)"},"suffix":{"text":"culture","meaning":"cultivation (耕作)"},"logic":"耕作田地，即「農業」。"}', 'agriculture industry / sustainable agriculture', '[{"en":"Agriculture is the main industry in this region.","zh-TW":"農業是這個地區的主要產業。"},{"en":"Modern agriculture relies heavily on technology.","zh-TW":"現代農業高度依賴技術。"}]', '{"adjective":"agricultural"}', NULL, 4, 98, NULL),
(99, 'ahead', '/əˈhɛd/', 'adverb', '{"zh-TW":["在前面；提前"],"en":["in front; in advance"]}', NULL, 'go ahead / ahead of time', '[{"en":"Go ahead, I''ll catch up.","zh-TW":"你先走，我趕上。"},{"en":"We finished ahead of schedule.","zh-TW":"我們提前完成了。"}]', NULL, NULL, 2, 99, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(100, 'aid', '/eɪd/', 'noun', '{"zh-TW":["援助；幫助"],"en":["help or support","financial or material assistance"]}', '{"root":{"text":"aid","meaning":"help (幫助)"},"logic":"直接表示「援助」。"}', 'financial aid / first aid / in aid of', '[{"en":"The government provided aid to flood victims.","zh-TW":"政府向洪災受害者提供援助。"},{"en":"Visual aids can enhance presentations.","zh-TW":"視覺輔助工具可以增強簡報效果。"}]', NULL, NULL, 1, 100, NULL),
(101, 'aim', '/eɪm/', 'verb', '{"zh-TW":["目標；瞄準","旨在"],"en":["to intend or plan","to point or direct toward a target"]}', '{"root":{"text":"aim","meaning":"estimate/direct (估算/指向)"},"logic":"指向某處，即「瞄準、旨在」。"}', 'aim to do / aim at / aim for', '[{"en":"We aim to increase revenue by 20% this year.","zh-TW":"我們的目標是今年營收增長20%。"},{"en":"The campaign is aimed at young professionals.","zh-TW":"該活動針對年輕專業人士。"}]', NULL, NULL, 1, 101, NULL),
(102, 'air', '/ɛr/', 'noun', '{"zh-TW":["【主要意義-名詞】空氣；空中","【次要意義-動詞】播出；播映（節目）","【次要意義-動詞】通風；晾曬","【次要意義-動詞】表達（意見/不滿）","【次要意義-名詞】神態；樣子"],"en":["[primary - noun] the invisible mixture of gases around us","[secondary - verb] to broadcast on radio or television","[secondary - verb] to ventilate a room or dry clothes in the open air","[secondary - verb] to express an opinion or grievance openly"]}', NULL, 'air a grievance / air a program / air time / on air / put on airs', '[{"en":"The documentary will be aired on the national broadcaster next week.","zh-TW":"這部紀錄片將於下週在國家廣播機構播出。"},{"en":"Employees were given the opportunity to air their grievances at the town hall.","zh-TW":"員工在員工大會上獲得了表達不滿的機會。"},{"en":"The show will go on air live at 9 PM tonight.","zh-TW":"該節目將於今晚9點進行現場直播。"}]', '{"noun":"airway, airing","adjective":"on-air"}', 'air 作動詞：air a program（播出節目）、air a grievance（表達不滿）均是 TOEIC 媒體和職場文章的高頻用法，on air（播出中）、airtime（播出時間）也常見。', 1, 102, NULL),
(103, 'aircraft', '/ˈɛərkræft/', 'noun', '{"zh-TW":["飛機；航空器"],"en":["a vehicle able to fly"]}', NULL, 'commercial aircraft / military aircraft', '[{"en":"The aircraft landed safely despite the storm.","zh-TW":"飛機在暴風雨中安全降落。"},{"en":"Modern aircraft use advanced navigation systems.","zh-TW":"現代飛機使用先進的導航系統。"}]', '{"adjective":"airborne"}', NULL, 3, 103, NULL),
(104, 'airline', '/ˈɛərlaɪn/', 'noun', '{"zh-TW":["航空公司"],"en":["a company providing air transport services"]}', NULL, 'major airline / budget airline', '[{"en":"The airline offers daily flights to Tokyo.","zh-TW":"這家航空公司提供每日飛往東京的航班。"},{"en":"She booked her ticket through the airline website.","zh-TW":"她透過航空公司網站預訂機票。"}]', '{"verb":"fly","adjective":"aerial"}', NULL, 3, 104, NULL),
(105, 'airport', '/ˈɛərpɔːrt/', 'noun', '{"zh-TW":["機場"],"en":["a place where aircraft take off and land"]}', NULL, 'international airport / regional airport', '[{"en":"We arrived at the airport two hours before departure.","zh-TW":"我們在出發前兩小時抵達機場。"},{"en":"The new airport terminal opened last year.","zh-TW":"新的航站樓去年開幕。"}]', '{"verb":"depart"}', NULL, 3, 105, NULL),
(106, 'aisle', '/aɪl/', 'noun', '{"zh-TW":["走道；通道"],"en":["a passage between rows of shelves or seats"]}', '{"root":{"text":"aisle","meaning":"passage (通道)"},"logic":"源自拉丁語 ala（翼），指建築內的側通道。"}', 'walk down the aisle / aisle seat', '[{"en":"You can find the cereal in aisle three.","zh-TW":"你可以在第三走道找到麥片。"},{"en":"She prefers an aisle seat on the plane.","zh-TW":"她偏好飛機上的走道座位。"}]', NULL, NULL, 2, 106, NULL),
(107, 'alert', '/əˈlɜːrt/', 'adjective', '{"zh-TW":["警覺的；警報"],"en":["quick to notice and respond to danger"]}', '{"root":{"text":"alert","meaning":"on the watch (警戒)"},"logic":"源自義大利語 all''erta（在瞭望台上）。"}', 'stay alert / alert system / high alert', '[{"en":"Drivers should stay alert at all times.","zh-TW":"駕駛人應隨時保持警覺。"},{"en":"The system sends an alert when errors occur.","zh-TW":"系統在發生錯誤時發送警報。"}]', '{"noun":"alert","verb":"alert"}', NULL, 2, 107, 258),
(108, 'algorithm', '/ˈælɡərɪðəm/', 'noun', '{"zh-TW":["演算法"],"en":["a set of rules for solving a problem"]}', NULL, 'search algorithm / algorithm design', '[{"en":"The algorithm sorts data efficiently.","zh-TW":"這個演算法能有效地排序資料。"},{"en":"Social media algorithms control what you see.","zh-TW":"社群媒體演算法控制你看到的內容。"}]', '{"adjective":"algorithmic"}', NULL, 3, 108, NULL),
(109, 'align', '/əˈlaɪn/', 'verb', '{"zh-TW":["對齊；使一致"],"en":["to arrange things in a line or to ensure consistency between things"]}', NULL, 'align goals / align teams / align with strategy', '[{"en":"The new policy aligns employee incentives with company objectives.","zh-TW":"新政策使員工激勵與公司目標保持一致。"},{"en":"The departments aligned their priorities before the budget review.","zh-TW":"各部門在預算審查前調整了其優先事項。"}]', '{"noun":"alignment","adjective":"aligned"}', NULL, 2, 109, 641),
(110, 'alive', '/əˈlaɪv/', 'adjective', '{"zh-TW":["活著的；有生氣的","活著的；有活力的","活著的；活躍的"],"en":["living; not dead","full of energy","living; full of energy"]}', NULL, 'stay alive / come alive', '[{"en":"The tradition is still alive today.","zh-TW":"這個傳統至今仍然存在。"},{"en":"The market comes alive on weekends.","zh-TW":"市場在週末變得熱鬧起來。"},{"en":"He was found alive after three days.","zh-TW":"三天後他被發現還活著。"},{"en":"The city comes alive at night.","zh-TW":"城市在夜晚活躍起來。"},{"en":"He is lucky to be alive after the accident.","zh-TW":"他在事故後還活著很幸運。"},{"en":"The city comes alive at night.","zh-TW":"這座城市在夜晚變得活躍起來。"}]', '{"adjective":"alive"}', NULL, 2, 110, NULL),
(111, 'allegation', '/ˌæləˈɡeɪʃən/', 'noun', '{"zh-TW":["指控；指稱"],"en":["a claim that someone has done something wrong, without proof"]}', NULL, 'make an allegation / deny the allegation / allegation of fraud', '[{"en":"The allegation of fraud triggered an internal investigation.","zh-TW":"詐欺指控引發了內部調查。"},{"en":"She denied all allegations made against her.","zh-TW":"她否認了針對她的所有指控。"}]', '{"verb":"allege","adjective":"alleged"}', NULL, 4, 111, NULL),
(112, 'allergen', '/ˈælədʒən/', 'noun', '{"zh-TW":["過敏原"],"en":["a substance that causes an allergic reaction"]}', NULL, 'common allergen / allergen information', '[{"en":"Please inform the server of any allergens before ordering.","zh-TW":"點餐前請告知服務員任何過敏原。"},{"en":"The menu clearly lists all allergens in each dish.","zh-TW":"菜單清楚列出每道菜的所有過敏原。"}]', '{"adjective":"allergenic","noun":"allergy"}', NULL, 3, 112, NULL),
(113, 'allergy', '/ˈælərdʒi/', 'noun', '{"zh-TW":["過敏症"],"en":["an adverse reaction of the immune system to a substance"]}', NULL, 'food allergy / seasonal allergy', '[{"en":"She has a severe allergy to peanuts.","zh-TW":"她對花生有嚴重過敏症。"},{"en":"Please inform your doctor about all known allergies.","zh-TW":"請告知您的醫生所有已知的過敏症。"}]', '{"adjective":"allergic","noun":"allergen"}', NULL, 3, 113, NULL),
(114, 'alliance', 'əˈlaɪəns', 'noun', '{"zh-TW":["聯盟；結盟","同盟"],"en":["a formal agreement between parties","a partnership"]}', NULL, 'strategic alliance/form an alliance', '[{"en":"We formed a strategic alliance with our partner.","zh-TW":"我們與合作夥伴建立了戰略聯盟。"}]', '{"adjective":"allied"}', NULL, 3, 114, NULL),
(115, 'allocate', '/ˈæləkeɪt/', 'verb', '{"zh-TW":["分配；撥出","分配"],"en":["to distribute resources for a particular purpose","to distribute for a particular purpose"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"loc","meaning":"place (地方)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向特定地方，即「分配」。"}', 'allocate funds/resources/budget; allocate resources / allocate funds', '[{"en":"The company allocated $2 million for R&D.","zh-TW":"公司撥出200萬美元用於研發。"},{"en":"Resources should be allocated based on priority.","zh-TW":"資源應根據優先順序分配。"},{"en":"The government allocated funds for education.","zh-TW":"政府撥款用於教育。"},{"en":"We need to allocate more time to this project.","zh-TW":"我們需要為這個專案分配更多時間。"}]', '{"noun":"allocation"}', NULL, 3, 115, 4),
(116, 'allocation', '/ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["分配；撥款"],"en":["the distribution of resources, funds, or tasks to specific purposes"]}', NULL, 'budget allocation / resource allocation / allocation of funds', '[{"en":"Fair allocation of tasks prevented burnout in the team.","zh-TW":"公平的任務分配防止了團隊倦怠。"},{"en":"Budget allocation decisions are made at the executive level.","zh-TW":"預算分配決策在高管層面做出。"}]', '{"verb":"allocate","adjective":"allocated"}', NULL, 4, 116, 500),
(117, 'allotment', '/əˈlɒtmənt/', 'noun', '{"zh-TW":["分配；配額；配售"],"en":["the distribution of shares or resources among applicants or participants"]}', NULL, 'allotment of shares / allotment notice / allotment of resources', '[{"en":"Employees received an allotment of shares at the company''s IPO.","zh-TW":"員工在公司首次公開招股時獲得了股份配售。"},{"en":"The budget committee approved the allotment of funds to each department.","zh-TW":"預算委員會批准了向各部門的資金分配。"}]', '{"verb":"allot","adjective":"allotted"}', NULL, 3, 117, 745),
(118, 'allow', '/əˈlaʊ/', 'verb', '{"zh-TW":["允許；准許","允許；容許"],"en":["to give permission for","to make something possible","to let someone do something","to give permission; to make it possible"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"low","meaning":"approve (批准)"},"logic":"朝向批准，即「允許」。"}', 'allow sb to do / allow for; allow for / not allowed; allow sb to do sth / be allowed to', '[{"en":"The policy allows employees to work from home.","zh-TW":"該政策允許員工在家工作。"},{"en":"Please allow 3-5 business days for processing.","zh-TW":"請預留3-5個工作天處理。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不准吸煙。"},{"en":"Allow two weeks for delivery.","zh-TW":"請預留兩週送貨時間。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不允許吸菸。"},{"en":"Please allow two weeks for delivery.","zh-TW":"請預留兩週的配送時間。"}]', '{"noun":"allowance","adjective":"allowable"}', NULL, 2, 118, NULL),
(119, 'allowance', 'əˈlaʊəns', 'noun', '{"zh-TW":["津貼；補貼","額度"],"en":["a regular amount of money","an amount permitted"]}', NULL, 'travel allowance/housing allowance', '[{"en":"You are entitled to a travel allowance.","zh-TW":"您有權獲得差旅津貼。"}]', '{"verb":"allow","adjective":"allowable"}', NULL, 3, 119, 259),
(120, 'alone', '/əˈloʊn/', 'adjective', '{"zh-TW":["獨自的；單獨的","單獨的；獨自的","獨自的；單獨地"],"en":["without other people","without other people; only"]}', NULL, 'leave alone / stand alone; leave alone / all alone; leave sb alone / let alone (更不用說)', '[{"en":"She prefers to work alone.","zh-TW":"她偏好獨自工作。"},{"en":"You are not alone in this.","zh-TW":"你不是一個人面對這件事。"},{"en":"She lives alone.","zh-TW":"她獨自生活。"},{"en":"Leave me alone, please.","zh-TW":"請讓我一個人待著。"},{"en":"She lives alone in a small apartment.","zh-TW":"她獨自住在一間小公寓裡。"},{"en":"Leave me alone, please.","zh-TW":"請別打擾我。"}]', '{"adjective":"alone","adverb":"alone"}', NULL, 2, 120, NULL),
(121, 'along', '/əˈlɒŋ/', 'preposition', '{"zh-TW":["沿著；一起"],"en":["moving forward on"]}', NULL, 'along with / get along', '[{"en":"We walked along the river.","zh-TW":"我們沿著河邊散步。"},{"en":"She gets along with everyone.","zh-TW":"她和每個人都相處得很好。"}]', NULL, NULL, 2, 121, NULL),
(122, 'already', '/ɔːlˈrɛdi/', 'adverb', '{"zh-TW":["已經"],"en":["before now or a specified time","before now or before a particular time"]}', NULL, 'already done / already know; already + 完成式', '[{"en":"The report is already finished.","zh-TW":"報告已經完成了。"},{"en":"We have already discussed this.","zh-TW":"我們已經討論過這件事了。"},{"en":"I''ve already eaten lunch.","zh-TW":"我已經吃過午餐了。"},{"en":"She already knows the answer.","zh-TW":"她已經知道答案了。"},{"en":"I''ve already finished my homework.","zh-TW":"我已經完成作業了。"},{"en":"The train had already left when we arrived.","zh-TW":"我們到達時火車已經開走了。"}]', '{"adverb":"already"}', NULL, 3, 122, NULL),
(123, 'also', '/ˈɔːlsoʊ/', 'adverb', '{"zh-TW":["也；而且"],"en":["in addition; too"]}', NULL, 'also known as / but also', '[{"en":"He also speaks French.","zh-TW":"他也說法語。"},{"en":"She is not only smart but also kind.","zh-TW":"她不僅聰明而且善良。"}]', NULL, NULL, 1, 123, NULL),
(124, 'alter', '/ˈɔːltər/', 'verb', '{"zh-TW":["改變；修改"],"en":["to change or make different"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"logic":"使成為其他樣子，即「改變」。"}', 'alter plans/design/course', '[{"en":"The company altered its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"Circumstances may alter the timeline.","zh-TW":"情況可能改變時間表。"}]', '{"noun":"alteration","adjective":"alternate"}', NULL, 2, 124, NULL),
(125, 'alternative', '/ɔːlˈtɜːrnətɪv/', 'noun', '{"zh-TW":["替代方案；選擇"],"en":["one of two or more available possibilities"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"suffix":{"text":"-ative","meaning":"relating to (有關的)"},"logic":"與其他有關的，即「替代方案」。"}', 'alternative solution/approach/option', '[{"en":"We need to find an alternative to the current supplier.","zh-TW":"我們需要找到目前供應商的替代方案。"},{"en":"What are the alternatives if the deal falls through?","zh-TW":"如果交易失敗，有什麼替代方案？"}]', '{"adverb":"alternatively"}', NULL, 4, 125, 260),
(126, 'alternatively', '/ɔːlˈtɜːrnətɪvli/', 'adverb', '{"zh-TW":["或者；作為替代"],"en":["in a way that offers a choice between two or more things"]}', NULL, 'alternatively, you may / choose alternatively', '[{"en":"You can pay online, or alternatively, at our office.","zh-TW":"您可以在線支付，或者也可以在我們的辦公室支付。"},{"en":"We can meet on Tuesday, or alternatively on Friday.","zh-TW":"我們可以在週二會面，或者也可以在週五。"}]', '{"adjective":"alternative","noun":"alternative"}', NULL, 5, 126, NULL),
(127, 'although', '/ɔːlˈðoʊ/', 'conjunction', '{"zh-TW":["雖然；儘管"],"en":["despite the fact that"]}', NULL, 'although... still; although = though (較口語)', '[{"en":"Although it rained, we went out.","zh-TW":"雖然下雨了，我們還是出門了。"},{"en":"Although tired, she kept working.","zh-TW":"雖然累了，她仍繼續工作。"},{"en":"Although it was raining, we went out.","zh-TW":"雖然在下雨，我們還是出去了。"},{"en":"Although expensive, the product is worth it.","zh-TW":"雖然貴，但這個產品值得。"}]', NULL, NULL, 3, 127, NULL),
(128, 'alumni', '/əˈlʌmnaɪ/', 'noun', '{"zh-TW":["校友"],"en":["former students of a school or university"]}', NULL, 'alumni association / alumni network', '[{"en":"The alumni donated to the school.","zh-TW":"校友們捐款給學校。"},{"en":"She joined the alumni association.","zh-TW":"她加入了校友會。"}]', NULL, NULL, 2, 128, NULL),
(129, 'always', '/ˈɔːlweɪz/', 'adverb', '{"zh-TW":["總是；一直"],"en":["at all times"]}', NULL, 'always available / as always', '[{"en":"He is always punctual.","zh-TW":"他總是很準時。"},{"en":"Customers always come first.","zh-TW":"客戶永遠是第一位的。"}]', '{"adverb":"always"}', NULL, 2, 129, NULL),
(130, 'amalgamate', '/əˈmælɡəmeɪt/', 'verb', '{"zh-TW":["合併；融合"],"en":["to combine or unite to form one organization or structure"]}', NULL, 'amalgamate companies / amalgamate departments', '[{"en":"The two regional offices were amalgamated into one.","zh-TW":"兩個區域辦公室被合併為一個。"},{"en":"The union decided to amalgamate with a larger federation.","zh-TW":"工會決定與一個更大的聯合會合併。"}]', '{"noun":"amalgamation","adjective":"amalgamated"}', NULL, 4, 130, NULL),
(131, 'amazing', '/əˈmeɪzɪŋ/', 'adjective', '{"zh-TW":["令人驚嘆的；了不起的"],"en":["extremely surprising or impressive"]}', NULL, 'amazing + 名詞 / It''s amazing that...', '[{"en":"The view from the top was amazing.","zh-TW":"從頂端看下去的景色令人驚嘆。"},{"en":"She did an amazing job on the project.","zh-TW":"她在專案中表現出色。"}]', '{"verb":"amaze","noun":"amazement","adverb":"amazingly"}', NULL, 3, 131, NULL),
(132, 'ambitious', '/æmˈbɪʃəs/', 'adjective', '{"zh-TW":["有野心的；雄心勃勃的"],"en":["having a strong desire to succeed","requiring great effort"]}', '{"root":{"text":"ambi","meaning":"go around (四處走)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿四處尋求機會的特質，即「有野心的」。"}', 'ambitious plan/goal/target; ambitious goal / ambitious plan', '[{"en":"The company set ambitious growth targets for next year.","zh-TW":"公司為明年設定了雄心勃勃的成長目標。"},{"en":"She is an ambitious young professional.","zh-TW":"她是一位有抱負的年輕專業人士。"},{"en":"She is an ambitious young woman.","zh-TW":"她是個有抱負的年輕女性。"},{"en":"The project is ambitious but achievable.","zh-TW":"這個計畫雄心勃勃但可實現。"}]', '{"noun":"ambition","adverb":"ambitiously"}', NULL, 3, 132, 823),
(133, 'ambulance', '/ˈæmbjʊləns/', 'noun', '{"zh-TW":["救護車"],"en":["a vehicle for taking sick people to hospital"]}', NULL, 'call an ambulance / emergency ambulance', '[{"en":"Call an ambulance immediately if someone collapses.","zh-TW":"如果有人倒下，立即叫救護車。"},{"en":"The ambulance arrived within five minutes.","zh-TW":"救護車在五分鐘內到達。"}]', NULL, NULL, 3, 133, NULL),
(134, 'amend', '/əˈmend/', 'verb', '{"zh-TW":["修正；修訂"],"en":["to make changes to improve or correct","to make changes to a document or law"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mend","meaning":"fault (過錯)"},"logic":"朝向修正過錯，即「修訂」。"}', 'amend a contract/law/policy; amend a law / amend the constitution', '[{"en":"The contract was amended to include new terms.","zh-TW":"合約被修訂以納入新條款。"},{"en":"Congress voted to amend the legislation.","zh-TW":"國會投票修正了該立法。"},{"en":"The committee voted to amend the proposal.","zh-TW":"委員會投票修正了提案。"},{"en":"The law was amended to include new provisions.","zh-TW":"法律被修訂以納入新條款。"}]', '{"noun":"amendment"}', NULL, 2, 134, 643),
(135, 'amendment', '/əˈmɛndmənt/', 'noun', '{"zh-TW":["修正案"],"en":["a change made to a law or document"]}', NULL, 'constitutional amendment / first amendment', '[{"en":"The First Amendment protects free speech.","zh-TW":"第一修正案保護言論自由。"},{"en":"They proposed an amendment to the bill.","zh-TW":"他們提議修改法案。"}]', '{"verb":"amend"}', NULL, 3, 135, 261),
(136, 'amenities', '/əˈmiːnɪtiz/', 'noun', '{"zh-TW":["設施；便民設施"],"en":["useful features that make a place pleasant or convenient"]}', NULL, 'local amenities / property amenities', '[{"en":"The apartment is close to many local amenities.","zh-TW":"這棟公寓靠近許多當地便民設施。"},{"en":"The development includes amenities such as a gym and pool.","zh-TW":"該開發項目包括健身房和游泳池等設施。"}]', NULL, NULL, 3, 136, NULL),
(137, 'amenity', '/əˈmiːnɪti/', 'noun', '{"zh-TW":["設施；便利設備"],"en":["a useful or desirable feature of a place"]}', NULL, 'hotel amenity / modern amenity', '[{"en":"The resort offers excellent amenities including a spa.","zh-TW":"度假村提供包括水療在內的優質設施。"},{"en":"Please check the list of in-room amenities.","zh-TW":"請查看客房設施清單。"}]', NULL, NULL, 3, 137, NULL),
(138, 'among', '/əˈmʌŋ/', 'preposition', '{"zh-TW":["在…之中","在...之中；之間"],"en":["in the middle of; surrounded by","in the middle of; between more than two"]}', NULL, 'among others / among the best; among others (其中)', '[{"en":"She is among the top candidates.","zh-TW":"她是頂尖的候選人之一。"},{"en":"Divide the tasks among the team.","zh-TW":"把任務分配給團隊成員。"},{"en":"She sat among her friends.","zh-TW":"她坐在朋友們中間。"},{"en":"He is among the best students.","zh-TW":"他是最好的學生之一。"},{"en":"She is popular among her colleagues.","zh-TW":"她在同事之間很受歡迎。"},{"en":"The cost was divided among the team members.","zh-TW":"費用在團隊成員之間分攤。"}]', '{"preposition":"among"}', NULL, 2, 138, NULL),
(139, 'amortization', '/əˌmɔːrtɪˈzeɪʃən/', 'noun', '{"zh-TW":["攤銷"],"en":["the gradual write-off of an intangible asset over time"]}', NULL, 'loan amortization / amortization schedule / amortization of goodwill', '[{"en":"The amortization of goodwill impacts reported earnings.","zh-TW":"商譽攤銷影響報告的盈利。"},{"en":"He prepared an amortization schedule for the loan.","zh-TW":"他為貸款準備了攤銷時間表。"}]', '{"verb":"amortize","adjective":"amortized"}', NULL, 4, 139, NULL),
(140, 'amortize', '/ˈæmɔːrtaɪz/', 'verb', '{"zh-TW":["攤銷；分期償還"],"en":["to spread the cost of an asset over its useful life"]}', NULL, 'amortize a loan / amortize intangible assets', '[{"en":"The loan was amortized over 10 years with equal monthly payments.","zh-TW":"貸款以等額月付方式在10年內攤銷。"},{"en":"Software development costs were amortized over five years.","zh-TW":"軟體開發成本在五年內攤銷。"}]', '{"noun":"amortization","adjective":"amortized"}', NULL, 3, 140, NULL),
(141, 'amount', '/əˈmaʊnt/', 'noun', '{"zh-TW":["金額；數量"],"en":["a quantity of something","the total of two or more quantities"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mount","meaning":"mountain (山)"},"logic":"朝向堆積如山，即「數量」。"}', 'a large/small amount of / total amount', '[{"en":"The total amount due is $5,000.","zh-TW":"應付總金額為5,000美元。"},{"en":"A significant amount of time was spent on research.","zh-TW":"大量時間被用於研究。"}]', NULL, NULL, 2, 141, NULL),
(142, 'analysis', 'əˈnæləsɪs', 'noun', '{"zh-TW":["分析；研究","分解"],"en":["a detailed examination","a study of data"]}', NULL, 'cost analysis/market analysis', '[{"en":"Please present a market analysis.","zh-TW":"請提交市場分析。"}]', '{"verb":"analyze","adjective":"analytical","adverb":"analytically"}', NULL, 3, 142, NULL),
(143, 'analyst', '/ˈænəlɪst/', 'noun', '{"zh-TW":["分析師；分析人員"],"en":["a professional who examines data or situations to draw conclusions"]}', NULL, 'financial analyst / business analyst / data analyst / market analyst', '[{"en":"The financial analyst issued a buy recommendation on the stock.","zh-TW":"財務分析師對該股票發出了買入建議。"},{"en":"She works as a business analyst in the strategy department.","zh-TW":"她在策略部門擔任業務分析師。"}]', '{"plural":"analysts","verb":"analyze"}', NULL, 3, 143, NULL),
(144, 'analytics', '/ˌænəˈlɪtɪks/', 'noun', '{"zh-TW":["分析；數據分析"],"en":["systematic computational analysis of data"]}', NULL, 'marketing analytics / data analytics', '[{"en":"Analytics revealed that most customers visit the site on mobile.","zh-TW":"分析顯示大多數顧客使用手機訪問網站。"},{"en":"The analytics team provided insights to improve the campaign.","zh-TW":"分析團隊提供了改進活動的見解。"}]', '{"verb":"analyze","adjective":"analytical"}', NULL, 3, 144, NULL),
(145, 'analyze', '/ˈænəlaɪz/', 'verb', '{"zh-TW":["分析；解析","分析"],"en":["to examine something in detail to understand it","to examine in detail"]}', '{"root":{"text":"ana","meaning":"up/throughout (全面)"},"suffix":{"text":"-lyze","meaning":"loosen/break down (分解)"},"logic":"全面分解，即「分析」。"}', 'analyze data/results/trends; analyze data / analyze results', '[{"en":"The team will analyze the survey results next week.","zh-TW":"團隊將在下週分析調查結果。"},{"en":"We need to analyze market trends before launching.","zh-TW":"推出前我們需要分析市場趨勢。"},{"en":"Scientists analyzed the data carefully.","zh-TW":"科學家仔細分析了數據。"},{"en":"We need to analyze the market trends.","zh-TW":"我們需要分析市場趨勢。"}]', '{"noun":"analysis","adjective":"analytical","noun2":"analyst"}', NULL, 3, 145, 262),
(146, 'anesthesia', '/ˌænɪsˈθiːziə/', 'noun', '{"zh-TW":["麻醉"],"en":["a state of induced insensitivity to pain for surgery"]}', NULL, 'general anesthesia / local anesthesia', '[{"en":"The patient was placed under general anesthesia for the operation.","zh-TW":"患者在手術中被施以全身麻醉。"},{"en":"Local anesthesia numbs only the specific area being treated.","zh-TW":"局部麻醉只會使正在治療的特定區域失去知覺。"}]', '{"noun":"anesthesiologist","adjective":"anesthetic"}', NULL, 4, 146, NULL),
(147, 'angry', '/ˈæŋɡri/', 'adjective', '{"zh-TW":["生氣的","生氣的；憤怒的"],"en":["feeling strong displeasure","feeling or showing strong displeasure"]}', NULL, 'get angry / angry about; angry at / angry about; angry with/at sb / angry about sth', '[{"en":"The customer was angry about the delay.","zh-TW":"顧客對延誤感到生氣。"},{"en":"Don''t make hasty decisions when angry.","zh-TW":"生氣時不要做倉促的決定。"},{"en":"She was angry about the delay.","zh-TW":"她對延誤感到生氣。"},{"en":"Don''t be angry with me.","zh-TW":"別對我生氣。"},{"en":"He was angry about the delay.","zh-TW":"他對延誤感到憤怒。"}]', '{"adjective":"angry","noun":"anger","adverb":"angrily","verb":"anger"}', NULL, 2, 147, NULL),
(148, 'animal', '/ˈænɪməl/', 'noun', '{"zh-TW":["動物"],"en":["a living creature that is not a plant or human","a living creature that can move and feel"]}', NULL, 'wild animal / animal rights; domestic/wild animal', '[{"en":"Dogs are loyal animals.","zh-TW":"狗是忠誠的動物。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨滅絕。"},{"en":"Dogs are popular domestic animals.","zh-TW":"狗是受歡迎的家畜。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨絕種。"}]', NULL, NULL, 2, 148, NULL),
(149, 'annex', '/ˈæneks/', 'noun', '{"zh-TW":["附件；附屬建築"],"en":["an addition or supplement to a document; also an attached building"]}', NULL, 'attach an annex / annex to the report / building annex', '[{"en":"The technical specifications are detailed in the annex.","zh-TW":"技術規格在附件中有詳細說明。"},{"en":"A new annex was constructed to expand the office capacity.","zh-TW":"建造了新的附屬建築以擴大辦公室容量。"}]', '{"verb":"annex","adjective":"annexed"}', NULL, 2, 149, 983);